entries[85666] = { ["name"] = "Zügel der donnernden Jadewolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 85\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange.\nBeschwört eine reitbare donnernde Jadewolkenschlange oder gibt sie wieder frei. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange.\nVerkaufspreis:" }
entries[85681] = { ["name"] = "Mjampignon", ["text"] = "Questgegenstand\n\"Fühlt sich etwas feucht an.\"" }
entries[85683] = { ["name"] = "Glyphe 'Aspekt des Wildtiers'", ["text"] = "Geringe Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Aspekt des Wildtiers'.\n\nDer Jäger nimmt die Aspekte eines Wildtiers an: Er kann nicht aufgespürt werden. Es kann immer nur jeweils ein Aspekt aktiv sein.\nVerkaufspreis:" }
entries[85684] = { ["name"] = "Glyphe 'Schwarzes Eis'", ["text"] = "Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr Euch im Effektbereich Eurer Frostfalle aufhaltet, wird Euer Bewegungstempo um 50% erhöht.\nVerkaufspreis:" }
entries[85685] = { ["name"] = "Glyphe 'Feuerodem'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr 'Feuerodem' gegen Ziele einsetzt, die von 'Benebelnde Dämpfe' betroffen sind, werden sie 3 Sek. lang desorientiert.\nVerkaufspreis:" }
entries[85687] = { ["name"] = "Glyphe 'Aufprall'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeit 'Aufprall' um 10 Meter.\nVerkaufspreis:" }
entries[85688] = { ["name"] = "Ein Schreiben von Lehrensucher Cho", ["text"] = "Questgegenstand\n\"Dieser versiegelte Schriftrollenbehälter ist in Lehrensucher Chos fließender Handschrift an Euch adressiert.\"\n<Zum Lesen rechtsklicken>" }
