entries[85691] = { ["name"] = "Glyphe 'Schutz'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Absorptionsmenge von 'Schutz' um 10%, dafür kann 'Schutz' nur magischen Schaden absorbieren.\nVerkaufspreis:" }
entries[85692] = { ["name"] = "Glyphe 'Manatee'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Manatee' ist nun ein Spontanzauber und zehrt zwei Aufladungen auf. Allerdings wird eine Abklingzeit von 10 Sek. ausgelöst.\nVerkaufspreis:" }
