entries[85695] = { ["name"] = "Glyphe 'Zenmeditation'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt nun 'Zenmeditation' in der Bewegung kanalisieren.\nVerkaufspreis:" }
entries[85696] = { ["name"] = "Glyphe 'Erneuernder Nebel'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Erneuernder Nebel' bewegt sich nun zum am weitesten entfernten verletzten Ziel innerhalb von 40 Metern statt zum nächsten verletzten Ziel innerhalb von 20 Metern.\nVerkaufspreis:" }
entries[85697] = { ["name"] = "Glyphe 'Wirbelnder Kranichtritt'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr bewegt Euch mit Eurer normalen Geschwindigkeit, während Ihr 'Wirbelnder Kranichtritt' einsetzt.\nVerkaufspreis:" }
entries[85698] = { ["name"] = "Glyphe 'Wirbelnde Feuerblüte'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Wirbelnde Feuerblüte' benötigt ein gegnerisches Ziel anstatt sich vorwärts zu bewegen. Dafür werden Ziele nicht mehr bewegungsunfähig gemacht.\nVerkaufspreis:" }
entries[85699] = { ["name"] = "Glyphe 'Wallender Nebel'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Wallender Nebel' benötigt kein Ziel mehr und heilt stattdessen das am schwersten verletzte Ziel innerhalb von 40 Metern.\nVerkaufspreis:" }
entries[85700] = { ["name"] = "Glyphe 'Berührung des Todes'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Berührung des Todes' kostet kein Chi mehr, dafür wird aber die Abklingzeit um 2 Minuten erhöht.\nVerkaufspreis:" }
