entries[86533] = { ["name"] = "Leuchtender Bern", ["text"] = "Questgegenstand\nEinzigartig\n\"Das sanfte Schimmern legt Euch nahe, dass es sich hierbei nicht um ein gewöhnliches Stück Bern handelt.\"" }
