entries[86563] = { ["name"] = "Hohles Schilfrohr", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Wasserschreiter beschwört.\nMit Rechtsklick Euren Wasserschreiter beschwören oder wieder freigeben." }
entries[86564] = { ["name"] = "Erfülltes Jadefragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Schleifer beschwört.\nIhr könnt den Schleifer mit einem Rechtsklick beschwören und entlassen." }
entries[86565] = { ["name"] = "Schlachthorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Schmettert ins Horn, was Gegner in einem Umkreis von 40 Metern anzieht. (2 Min Abklingzeit)\n\"Wird von Yaungolspähern getragen, um im Falle eines Angriffs Verbündete zu alarmieren.\"" }
entries[86566] = { ["name"] = "Sammlerhandschuhe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHände Stoff\n9 Rüstung\nHaltbarkeit 20 / 20\nBenötigt Stufe 85\nAnlegen: Ermöglicht schnelleres Sammeln von Ressourcen in Pandaria.\n\"Schützt gegen scharfkantige Steine und Dornen.\"" }
entries[86567] = { ["name"] = "Yaungolwindspiel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\nBenutzen: Stürmt auf einen Gegner zu, fügt Gegnern in einem Umkreis von 8 Metern 50000 körperlichen Schaden zu und stößt sie 2 Sek. lang zu Boden. (2 Min Abklingzeit)\n\"Wird von Yaungolmedizinmännern verwendet, um Wetteränderungen zu erahnen.\"\nVerkaufspreis:" }
entries[86568] = { ["name"] = "Handlanger Peins Messingkompass", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Setzt die Erinnerungen eines längst vergessenen Ersten Maats frei. (Procchance: 5%, 3Min. Abklingzeit) (2 Std. Abklingzeit)" }
entries[86569] = { ["name"] = "Kristall des Wahnsinns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 85\nBenutzen: Erhöht 1 Stunde lang alle Werte um 500 . Zählt sowohl als Kampf- als auch als Wächterelixier. (15 Min Abklingzeit)\n\"Es wirkt fast, als ob er Euch... anstarrt.\"" }
entries[86570] = { ["name"] = "Kiste mit entführten Welpen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\nBenutzen: Befreit die entführten Welpen, die 10 Min. lang für Euch kämpfen. (1 Stunde Abklingzeit)\n\"...und sie essen Welpen!\"\nVerkaufspreis:" }
